      TopicListScreen(subject: 'सामान्य ज्ञान व विज्ञान', isGuest: widget.isGuest, isEnglish: _isEnglish, onToggleLang: _toggleLanguage),
      QuickTypeScreen(testType: 'PYQ', isGuest: widget.isGuest, isEnglish: _isEnglish),
