class MockSetsScreen extends StatelessWidget {
  final bool isGuest;
  final bool isEnglish;
  const MockSetsScreen({super.key, required this.isGuest, required this.isEnglish});

  @override
  Widget build(BuildContext context) {
    final Map<String, List<QuestionItem>> grouped = {};
    for (final q in sampleQuestions) {
      if (q.setName.startsWith('GK Mega Mock')) {
        grouped.putIfAbsent(q.setName, () => []).add(q);
      }
    }
    final keys = grouped.keys.toList();

    return Scaffold(
      appBar: AppBar(
        title: Text('GK मॉक टेस्ट सेट्स (${keys.length} सेट)', style: const TextStyle(fontSize: 16)),
        backgroundColor: const Color(0xFF151C2C),
      ),
      body: keys.isEmpty
          ? const Center(child: Text('कोई मॉक सेट उपलब्ध नहीं है'))
          : ListView.builder(
              padding: const EdgeInsets.all(16),
              itemCount: keys.length,
              itemBuilder: (context, index) {
                final setName = keys[index];
                final qs = grouped[setName]!;
                return Card(
                  color: const Color(0xFF1A2130),
                  margin: const EdgeInsets.only(bottom: 10),
                  shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
                  child: ListTile(
                    leading: CircleAvatar(
                      backgroundColor: Colors.orangeAccent.withOpacity(0.2),
                      child: Text('${index + 1}', style: const TextStyle(color: Colors.orangeAccent, fontWeight: FontWeight.bold)),
                    ),
                    title: Text(setName, style: const TextStyle(fontWeight: FontWeight.bold, color: Colors.white)),
                    subtitle: Text('कुल प्रश्न: ${qs.length} • मिश्रित विषय', style: const TextStyle(fontSize: 12, color: Colors.grey)),
                    trailing: ElevatedButton(
                      style: ElevatedButton.styleFrom(backgroundColor: Colors.green.shade700),
                      onPressed: () {
                        Navigator.push(
                          context,
                          MaterialPageRoute(
                            builder: (context) => QuizPlayScreen(
                              title: setName,
                              questions: qs,
                              isGuest: isGuest,
                              isEnglish: isEnglish,
                            ),
                          ),
                        );
                      },
                      child: const Text('Start', style: TextStyle(color: Colors.white, fontSize: 12)),
                    ),
                  ),
                );
              },
            ),
    );
  }
}

